"""Brasil / Ciências: 1º e 2º ano (BNCC EF01CI01–EF01CI06, EF02CI01–EF02CI08)"""
from br_sci import H, it

D = "A que corresponde esta descrição: {v}?"


SOL = [("a camiseta preta", "a camiseta branca"), ("o asfalto", "a calçada clara"), ("o carro preto", "o carro branco"), ("a areia da praia", "a água do mar"),
       ("o telhado escuro", "o telhado branco"), ("a bola azul-escura", "a bola amarela"), ("a terra escura", "a areia clara"), ("o boné preto", "o boné branco"),
       ("o banco de metal escuro", "o banco de madeira clara"), ("a pedra escura", "a pedra clara"), ("a mochila preta", "a mochila branca"),
       ("a panela preta", "a panela prateada"), ("o pneu", "o papel branco"), ("o chão de terra", "a poça de água")]


def f_sol(R):
    a, b = R.choice(SOL)
    x, y = (a, b) if R.random() < 0.5 else (b, a)
    return it("No sol forte, o que esquenta mais: %s ou %s?" % (x, y), a, [b, "os dois esquentam igual", "nenhum dos dois esquenta"],
              a[0].upper() + a[1:] + " esquenta mais. Superfícies escuras absorvem mais luz, e a terra e a areia esquentam mais rápido do que a água.")


